def topla(*args: int) -> int:
    """Sınırsız sayıda argüman alır."""
    return sum(args)

def bilgi(**kwargs) -> None:
    """Anahtar-değer çifti alır."""
    for k, v in kwargs.items():
        print(f'{k}: {v}')

print(topla(1, 2, 3, 4))     # 10
bilgi(isim='Efe', yas=20)    # isim: Efe / yas: 20
